FolderProperties = {
    init: async function (app, container, folder) {
        app = app || session.app;
        container = container || $(".component[name=FolderProperties]");
        BootstrapTabs.upgradeLegacy($("[name=tabs]", container));

        FolderRoles.init(app, $(".component[name=FolderRoles]", $("[name=roles]", container)), folder);
        FolderEventManager.init(app, $(".component[name=FolderEventManager]", $("[name=events]", container)), folder);
    }
}
